&= \cos (2 \angle AOM) \\
&= 2 \cos^2 \angle AOM - 1 \\
&= 2 \left( -\frac{1}{\sqrt{55}} \right)^2 - 1 \\
&= \boxed{-\frac{53}{55}}.
\end{align*}

